class BaseChoose {
    constructor({prevEl, el, nextEl, btnConfig = {}}) {
        const { backBtn, backBtnCallback, nextBtn, nextBtnCallback, } = btnConfig

        this.prevDOM = this.prevDOM || this.$$(prevEl)
        this.DOM = this.DOM || this.$$(el)
        this.nextDOM = this.nextDOM || this.$$(nextEl)
        this.backBtn = this.backBtn || this.$$(backBtn)
        this.nextBtn = this.nextBtn || this.$$(nextBtn)

        // title DOM
        this.titleDOM = this.titleDOM || this.$$('[data-title]')

        // 清楚全部 按钮
        this.clearAllBtn = this.clearAllBtn || this.$$('[data-clear-all]')

        if (this.backBtn) {
            this.backBtn.onclick = () => this.btnClickHook('back', backBtnCallback)
        }
        if (this.nextBtn) {
            this.nextBtn.onclick = () => this.btnClickHook('next', nextBtnCallback)
        }
    }
    $$(entity) {
        return entity ? document.querySelector(entity) : null
    }
    // 数据埋码
    GAEvent(params) {
        window.dataLayer.push({ "event_parameters": null });
        window.dataLayer.push({
            "event":"ga4Event",
            "event_name":"how_to_choose",
            "event_parameters":{
                "current_page": window.location.href, // current page url
                ...params
            }
        });
    }
    btnClickHook(btnType, callback) {
        if (btnType === 'back') {
            this.prevDOM && (this.prevDOM.style.display = 'block')
            this.DOM && (this.DOM.style.display = 'none')
        }
        if (btnType === 'next') {
            this.nextDOM && (this.nextDOM.style.display = 'block')
            this.DOM && (this.DOM.style.display = 'none')
        }
        this.scrollToHelpMeDOM()

        callback && callback()
    }
    // 更新 step
    updateStep(step = 1, direction) {
        const activeStep = this.$$('[data-step-active]')
        if (direction === 'prev') {
            const prevEle = activeStep.previousElementSibling
            if (prevEle) {
                activeStep.classList.remove('active')
                activeStep.classList.remove('finish')
                activeStep.removeAttribute('data-step-active')
                prevEle.classList.add('active')
                prevEle.classList.remove('finish')
                prevEle.setAttribute('data-step-active', '')
            }
        }
        if (direction === 'next') {
            const nextEle = activeStep.nextElementSibling
            if (nextEle) {
                activeStep.classList.remove('active')
                activeStep.classList.add('finish')
                activeStep.removeAttribute('data-step-active')
                nextEle.classList.add('active')
                nextEle.setAttribute('data-step-active', '')
            }
        }

        // 更新 页面 title
        const titleArray = this.titleDOM.dataset.titleString.split(',')
        this.titleDOM.innerHTML = titleArray[step - 1]
    }
    // 滚动到 动态内容 DOM
    scrollToHelpMeDOM(callback) {
        const helpMeOffsetTop = this.$$('#shopify-section-page-help-me').offsetTop
        const headerHeight =this.$$('.site-header')?.offsetHeight || this.$$('jky-header')?.offsetHeight || this.$$('header-v5')?.offsetHeight || 0
        window.scrollTo({
            top: helpMeOffsetTop - headerHeight,
            behavior: 'smooth',
        })
        callback && callback()
    }
    // 注册监听事件
    addEventListener(el, event, fn) {
        const target = el ? document.querySelector(el) : window
        target.addEventListener(event, fn.bind(this))
    }
    // 移除监听事件
    removeEventListener(el, event, fn) {
        const target = el ? document.querySelector(el) : window
        target.removeEventListener(event, fn.bind(this))
    }
    matchContent(param) {

        const RegExp = /\[([^\]]*)\]/ // 摘取 [] 内的内容
        const result = param.match(RegExp)
        return result ? result[1] : ''
    }
    // 获取商品延保信息
    async getProductWarranty(id) {
        try {
            const { data: { productWarranty, } } = await getProductWarrantyInfo({ skuId: id, })

            const warrantyKey = `${howToChoose.warrantyKey}`
            const warrantyContent = `${howToChoose.warrantyContent}`
            let warrantyProperty = Object.create(null)
            if (productWarranty) {
                warrantyProperty[warrantyKey] = warrantyContent
            }

            return warrantyProperty
        } catch {
            return Object.create(null)
        }
    }
    // 加入购物车
    async addToCart(id, quantity = 1, properties = {}) {
        const warrantyProperty = await this.getProductWarranty(id)

        let cart = document.querySelector('cart-notification') || document.querySelector('cart-drawer');
        addItem(id, {
            quantity,
            properties: {
                SmartShopOrder: '',
                // ...warrantyProperty, 暂时不需要再购物车展示延保信息
                ...properties,
            },
        }).then(response => {
            cart.renderContents(response)
        })
        .catch((e) => {
            console.error(e);
        })
        .finally(() => {
            if (cart && cart.classList.contains('is-empty')) cart.classList.remove('is-empty')

            document.querySelectorAll('[data-advantage-add-to-cart]').forEach( it => it.classList.remove('btn--loading'))
            document.querySelectorAll('[data-end-add-to-cart]').forEach( it => it.classList.remove('btn--loading'))
        });
    }
    // buy now
    async buyNow(id) {
        const params =  [{ id, quantity: 1, properties: { Action: 'SmartShopOrder' }}]
        try {
            const checkoutUrl = await createCartAndCheckout(params)
            if (checkoutUrl) {
                window.location.href = checkoutUrl
            }
        } catch (error) {
            const params = { SmartShopOrder: '', }
            const properties = window.btoa(unescape(encodeURIComponent(JSON.stringify({ ...params, }))))
            window.location.href = `/cart/${id}:1?traffic_source=buy_now&properties=${properties}`
        } finally {
            document.querySelectorAll('[data-end-buy-now]').forEach( it => it.classList.remove('btn--loading'))
        }
    }
}


// 开始选择
class StartChoose extends BaseChoose {
    constructor({ ...props }) {
        super({ ...props })

        this.init()

        if (document.querySelector('[data-smart-shop-compare-link]')) {
            // 数据埋码 - Product Compare
            document.querySelector('[data-smart-shop-compare-link]').onclick = e => {
                const wrap = document.querySelector('[data-smart-shop-compare-wrap]')

                const position = wrap.querySelector('h2').innerText
                const button_name = e.target.nodeName === 'A' ? e.target.innerText : e.target.parentElement.innerText
                const link = e.target.nodeName === 'A' ? e.target.getAttribute('href') : e.target.parentElement.getAttribute('href')
                this.GAEvent({
                    module: 'sing_pic',
                    position,
                    button_name,
                    link,
                })
            }
        }
    }
    async init() {
        const { data = [] } = await getMainScene()
        const mainSceneDOM = this.$$('[data-main-scene]')
        const { otherText, otherPcImg, otherMbImg, } = mainSceneDOM.dataset

        let html = ''
        data.forEach(({ sceneMainId, sceneMainImageMobile, sceneMainImagePc, sceneMainName }, index) => {
            html += `
                <li
                    class="group ${index === 0 ? 'active' : ''} py-50 lg:j-py-20 cursor-pointer flex-shrink-0"
                    data-tab-id="${sceneMainId}"
                    data-tab="${sceneMainName}"
                    data-mb-img="${sceneMainImageMobile}"
                    data-pc-img="${sceneMainImagePc}"
                >
                    <span class="choose-tab">${sceneMainName}</span>
                </li>
            `
        })
        // 固定
        html += `
            <li
                class="group py-50 lg:j-py-20 cursor-pointer flex-shrink-0"
                data-tab-id=""
                data-tab="${otherText}"
                data-mb-img="${otherMbImg}"
                data-pc-img="${otherPcImg}"
            >
                <span class="choose-tab">${otherText}</span>
            </li>
        `
        mainSceneDOM.innerHTML = html

        this.tabs = this.DOM.querySelectorAll('[data-tab]') || []
        this.tabs.forEach(it => it.onclick = () => this.handleTabClick(it, otherText))

        // 默认激活第一个 tab
        this.handleTabClick(this.tabs[0], otherText)
    }
    handleTabClick(it, otherText) {
        this.tabs.forEach(v => v.classList.remove('active'))
        it.classList.add('active')

        const { mbImg, pcImg, tab, tabId, } = it.dataset

        const tabContentDom = this.$$('[data-tab-content]')
        tabContentDom.innerHTML = `
            <img loading="lazy" class="block lg:hidden w-full h-[100vw] object-cover" src="${mbImg}" alt="">
            <img loading="lazy" class="hidden lg:block w-full lg:j-h-560 object-cover" src="${pcImg}" alt="">
        `

        this.sceneMainName = tab
        this.sceneMainId = tabId
        this.$$('[data-tab-others]').style.display = this.sceneMainName === otherText ? 'block' : 'none'
    }
}
function initStartChoose() {
    const startchoose = new StartChoose({
        el: '#start',
        nextEl: '#question1',
        btnConfig: {
            nextBtn: '[data-start-next]',
            nextBtnCallback: () => {
                // 数据埋码
                const title = document.querySelector('[data-title]').innerText
                startchoose.GAEvent({
                    module: title,
                    position: startchoose.sceneMainName,
                })

                startchoose.updateStep(1)

                // 初始化 选择场景
                const chooseScenarios = initChooseScenarios(startchoose.sceneMainName, startchoose.sceneMainId)
                const { otherText, }= document.querySelector('[data-main-scene]')?.dataset || {}
                if (startchoose.sceneMainName === otherText) {
                    const inputVal = document.querySelector('[data-other-scene-input]')?.value?.trim()
                    inputVal && addOtherMainScene({ scene: inputVal })
                    chooseScenarios.nextBtn.onclick()
                }
            },
        },
    })
}


