function initChooseScenarios(sceneMainName, sceneMainId) {
    const chooseScenarios = new ChooseScenarios({
        sceneMainName,
        sceneMainId,

        prevEl: '#start',
        el: '#question1',
        nextEl: '#question2',

        btnConfig: {
            backBtn: '[data-question1-back]',
            backBtnCallback: () => {
                chooseScenarios.updateStep(1, 'prev')
            },
            nextBtn: '[data-question1-next]',
            nextBtnCallback: () => {
                //  数据埋码
                const title = document.querySelector('[data-title]').innerText
                const scenarios = document.querySelector('[data-scenarios]').innerText
                const sceneBoxes = chooseScenarios.DOM.querySelectorAll('[data-scene-checkbox]')
                Array.from(sceneBoxes).forEach(it => {
                    if (it.checked) {
                        const text = it.parentElement.nextElementSibling.innerText
                        chooseScenarios.GAEvent({
                            module: title,
                            position: scenarios,
                            button_name: text,
                        })
                    }
                })

                chooseScenarios.updateStep(2, 'next')

                // 初始化 选择电器
                initChooseAppliances(sceneMainId, chooseScenarios.sceneSubIdList, chooseScenarios)
            },
        },
    })
    return chooseScenarios
}


